+    public static String getExitCodeString(int code) {
+        switch (code) {
+        case TestRunner.CANCELLED:
+            return "Cancelled";
+        case TestRunner.FAILED:
+            return "Failed";
+        case TestRunner.PASSED:
+            return "Passed";
+        case TestRunner.SKIPPED:
+            return "Skipped";
+        default:
+            return "(" + code + ")";
+        }
+    }
